/* Move the existing recognition block into the final hero chapter, retaining its content. */
(()=>{'use strict';const clamp=x=>Math.max(0,Math.min(1,x)),range=(p,a,b)=>clamp((p-a)/(b-a));
window.VishwaTransitions={mount({hero,stage}){const recognition=document.querySelector('.recognition');if(!recognition)return null;const originalParent=recognition.parentNode,originalNext=recognition.nextSibling;const trust=document.createElement('div');trust.className='vx-trust-scene';trust.id='trusted-cinematic';trust.setAttribute('aria-label','Trusted by and program selections');trust.append(recognition);stage.append(trust);const label=recognition.querySelector('.trusted-label');if(label)label.textContent='Trusted by';const logoHolder=recognition.querySelector('.trusted-logos');const logos=[...logoHolder.children];logos.forEach((el,i)=>{const card=document.createElement('div');card.className='vx-partner';card.dataset.vtIndex=`0${i+1} / 0${logos.length}`;card.style.setProperty('--vt-direction',i-(logos.length-1)/2);el.before(card);card.append(el)});const cards=[...logoHolder.children];let lastCompact=null;
function update({progress:p,staticMode,mobile}){const compact=staticMode;if(compact!==lastCompact){if(compact)hero.after(trust);else stage.append(trust);lastCompact=compact}const entry=compact?1:range(p,.70,.80),light=compact?1:range(p,.91,1);trust.style.setProperty('--vt-entry',entry);trust.style.setProperty('--vt-light',light);trust.style.setProperty('--vt-programs',compact?1:range(p,.83,.9));trust.classList.toggle('vt-visible',entry>.8);cards.forEach((card,i)=>card.style.setProperty('--vt-card',compact?1:range(p,.72+i*.018,.82+i*.018)));hero.style.setProperty('--vx-exit',compact?0:light);hero.style.setProperty('--vt-canvas',compact?1:1-range(p,.72,.96)*.82);hero.style.setProperty('--vt-bottom',compact?1:1-range(p,.67,.73));}
return{element:trust,update,dispose(){logos.forEach(el=>logoHolder.append(el));cards.forEach(c=>c.remove());originalParent.insertBefore(recognition,originalNext);trust.remove()}};
}}})();
